using Windows.UI.Xaml.Input;

namespace UserActivityRecorder
{
    public class UserActivityRecorder
    {
        private static readonly string _logFilePath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "UserActivityRecorder.log");

        public static void StartRecording()
        {
            // Start recording user activity
            using (var writer = new StreamWriter(_logFilePath, append: true))
            {
                writer.WriteLine($"Recording started at {DateTime.Now}");
            }
        }

        public static void StopRecording()
        {
            // Stop recording user activity
            using (var writer = new StreamWriter(_logFilePath, append: true))
            {
                writer.WriteLine($"Recording stopped at {DateTime.Now}");
            }
        }

        public static void LogActivity(string activityType, string description)
        {
            // Log user activity
            using (var writer = new StreamWriter(_logFilePath, append: true))
            {
                writer.WriteLine($"Activity type: {activityType}, Description: {description}, Timestamp: {DateTime.Now}");
            }
        }
    }
}
